    public async Task GivenRelevantMalformedNativeAuthority_WhenPermanentlyDeleting_Then503WithoutAnyContentChange(string kind)
    {using var owner=new ProtectionFixture();using var client=new ProtectionFixture();var o=await Setup(owner);var s=await Setup(client);var target=await Create(o);var (c,g)=await Share(o,owner,s,client,CollectionGrantAccess.ReadWrite,[target.RecordId],[]);await using(var db=fixture.Context()){if(kind=="signature")await db.CollectionGrants.Where(x=>x.Id==g.Id).ExecuteUpdateAsync(x=>x.SetProperty(g=>g.RecipientKeyEnvelope,"bad"u8.ToArray()));if(kind=="numericString")await db.Collections.Where(x=>x.Id==c.Id).ExecuteUpdateAsync(x=>x.SetProperty(c=>c.Envelope,Encoding.UTF8.GetBytes(Encoding.UTF8.GetString(c.Envelope).Replace("\"keyEpoch\":1","\"keyEpoch\":\"1\""))));if(kind=="pins")await db.VaultProtections.Where(x=>x.AccountId==s.InternalId).ExecuteUpdateAsync(x=>x.SetProperty(p=>p.Material,"bad"u8.ToArray()));}var before=await Snapshot(o);using var r=await Permanent(s,target.RecordId,1);await Failure(r,503,"persistence_unavailable");Assert.Equal(before,await Snapshot(o));}    private static HttpRequestMessage DeletePermanent(State s,string path,byte[] body){var split=path.IndexOf('?');var uri=split<0?path+"/permanent":path[..split]+"/permanent"+path[split..];var r=Request(s,body,uri);r.Method=HttpMethod.Delete;return r;}
